/* Bagdi Kata – nyitó logóanimáció (betöltés előtt, 3 mp, látogatónként egyszer)
   Beillesztés: az index.html <head> részébe, a többi script ELÉ, defer nélkül (src="./bk-intro.js").
   Önálló fájl: a logó képként benne van, más fájl nem kell hozzá.
   Teszteléshez az oldal címe után: ?intro  -> mindig lejátssza (nem jegyzi meg). */
(function () {
  var KEY = 'bk_intro_seen', force = /[?&]intro\b/.test(location.search) || window.BK_INTRO_FORCE === true;
  try { if (!force && localStorage.getItem(KEY)) return; } catch (e) {}
  var MARK = 'data:image/png;base64,', WORD = 'data:image/png;base64,';
  var MIN = 3000, MAX = 7000, t0 = Date.now();
  var de = document.documentElement;

  var st = document.createElement('style');
  st.textContent =
    '#bk-intro{position:fixed;top:0;left:0;right:0;bottom:0;z-index:2147483000;background:#f6f3ee;display:-webkit-flex;display:flex;' +
    '-webkit-flex-direction:column;flex-direction:column;-webkit-align-items:center;align-items:center;-webkit-justify-content:center;justify-content:center;' +
    '-webkit-transition:opacity .6s ease;transition:opacity .6s ease}' +
    '#bk-intro.out{opacity:0}' +
    '#bk-intro canvas{width:250px;height:241px;max-width:46vw;max-height:44.4vw;display:block}' +
    '#bk-intro .w{display:block;width:320px;max-width:60vw;height:auto;margin-top:26px;opacity:0}' +
    'html.bk-intro-on,html.bk-intro-on body{overflow:hidden}';
  (document.head || de).appendChild(st);

  var el = document.createElement('div');
  el.id = 'bk-intro'; el.setAttribute('aria-hidden', 'true');
  var cv = document.createElement('canvas'), word = new Image();
  word.className = 'w'; word.alt = ''; word.src = WORD;
  el.appendChild(cv); el.appendChild(word);
  de.className += ' bk-intro-on';
  de.appendChild(el);

  // a rácsos szív 12 „szála” (a logó saját koordinátáiban: 105..199 × 85.5..176)
  var L = [[100,100,215,215],[90,295,210,175],[100,80,215,195],[90,275,210,155],[100,60,215,175],[90,255,210,135],
           [100,40,215,155],[90,235,210,115],[100,20,215,135],[90,215,210,95],[100,0,215,115],[90,195,210,75]];
  var mark = new Image(), ready = false;
  mark.onload = function () { ready = true; };
  mark.src = MARK;
  var off = document.createElement('canvas'), ox = off.getContext('2d'), ctx = cv.getContext('2d');
  var ease = function (t) { t = t < 0 ? 0 : t > 1 ? 1 : t; return t * t * (3 - 2 * t); };

  function frame() {
    var t = (Date.now() - t0) / 1000;
    var r = cv.getBoundingClientRect(), dpr = Math.min(2, window.devicePixelRatio || 1);
    var W = Math.max(1, Math.round(r.width * dpr)), H = Math.max(1, Math.round(r.height * dpr));
    if (cv.width !== W || cv.height !== H) { cv.width = off.width = W; cv.height = off.height = H; }
    ctx.clearRect(0, 0, W, H);
    if (ready) {
      var sx = W / 94, sy = H / 90.5;
      ctx.globalAlpha = .13; ctx.drawImage(mark, 0, 0, W, H); ctx.globalAlpha = 1;
      // szálak: mindegyik 0,1 mp késéssel, 0,55 mp alatt húzódik végig
      ox.globalCompositeOperation = 'source-over'; ox.clearRect(0, 0, W, H);
      ox.strokeStyle = '#000'; ox.lineCap = 'round'; ox.lineWidth = 22 * sx;
      for (var i = 0; i < L.length; i++) {
        var k = ease((t - i * .1) / .55); if (k <= 0) continue;
        var l = L[i], x0 = (l[0] - 105) * sx, y0 = (l[1] - 85.5) * sy, x1 = (l[2] - 105) * sx, y1 = (l[3] - 85.5) * sy;
        ox.beginPath(); ox.moveTo(x0, y0); ox.lineTo(x0 + (x1 - x0) * k, y0 + (y1 - y0) * k); ox.stroke();
      }
      ox.globalCompositeOperation = 'source-in'; ox.drawImage(mark, 0, 0, W, H);
      ctx.drawImage(off, 0, 0);
      var full = ease((t - 1.55) / .35);
      if (full > 0) { ctx.globalAlpha = full; ctx.drawImage(mark, 0, 0, W, H); ctx.globalAlpha = 1; }
    }
    // felirat: balról jobbra előtűnik
    var w = ease((t - 1.7) / .7);
    word.style.opacity = w;
    var cp = 'inset(0 ' + ((1 - w) * 100).toFixed(1) + '% 0 0)';
    word.style.webkitClipPath = cp; word.style.clipPath = cp;
    if (!done) schedule();
  }
  var schedule = window.requestAnimationFrame ? function () { var ok = false; requestAnimationFrame(function () { ok = true; frame(); }); setTimeout(function () { if (!ok) frame(); }, 50); }
                                              : function () { setTimeout(frame, 16); };

  var loaded = document.readyState === 'complete', done = false;
  function finish() {
    if (done) return; done = true;
    try { if (!force) localStorage.setItem(KEY, '1'); } catch (e) {}
    el.className = 'out';
    de.className = de.className.replace(/\s*bk-intro-on/g, '');
    setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 700);
  }
  function check() { if (Date.now() - t0 >= MIN && loaded) finish(); }
  window.addEventListener('load', function () { loaded = true; check(); });
  setTimeout(check, MIN); setTimeout(check, MIN + 500);
  setTimeout(finish, MAX);                       // biztonsági korlát lassú betöltésnél
  el.addEventListener('click', function () { if (Date.now() - t0 > 800) finish(); });
  frame();
})();
